package com.cinenest;
import com.nimbusds.jose.util.JSONObjectUtils;import java.net.*;import java.net.http.*;import java.nio.file.*;import java.util.*;import java.util.concurrent.*;import org.junit.jupiter.api.*;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.core.env.Environment;import org.springframework.jdbc.core.simple.JdbcClient;import org.springframework.test.context.*;import static org.assertj.core.api.Assertions.*;
@SpringBootTest(webEnvironment=SpringBootTest.WebEnvironment.RANDOM_PORT,properties={"cinenest.identity.profile.enabled=true","cinenest.identity.facebook.live-execution=false","cinenest.identity.google.live-execution=false","spring.datasource.hikari.maximum-pool-size=4","spring.datasource.hikari.minimum-idle=0"})
@org.springframework.test.annotation.DirtiesContext(classMode=org.springframework.test.annotation.DirtiesContext.ClassMode.AFTER_CLASS)
@ActiveProfiles("local-synthetic")
class CustomerProfileIntegrationTest {
 static final Path OUTBOX;static{try{OUTBOX=Files.createTempDirectory("cinenest-profile-mail-");}catch(Exception e){throw new ExceptionInInitializerError(e);}}
 static final String PASSWORD="Local profile synthetic secret 2026!";
 @Autowired JdbcClient jdbc;@Autowired Environment env;
 @DynamicPropertySource static void config(DynamicPropertyRegistry r){r.add("cinenest.identity.enabled",()->"true");r.add("cinenest.identity.manual.enabled",()->"true");r.add("cinenest.identity.session-timeout-seconds",()->"120");r.add("cinenest.identity.manual.outbox",OUTBOX::toString);}
 @BeforeEach void isolateThrottle(){jdbc.sql("TRUNCATE cinenest_identity.manual_throttle").update();}
 String base(){return "http://127.0.0.1:"+env.getRequiredProperty("local.server.port");}
 final class Browser {
  String cookie,csrf;
  final HttpClient client=HttpClient.newBuilder().followRedirects(HttpClient.Redirect.NEVER).build();
  HttpResponse<String> call(String method,String path,String body,boolean token)throws Exception{var b=HttpRequest.newBuilder(URI.create(base()+path)).method(method,body==null?HttpRequest.BodyPublishers.noBody():HttpRequest.BodyPublishers.ofString(body));if(cookie!=null)b.header("Cookie",cookie);if(body!=null)b.header("Content-Type","application/json");if(token&&csrf!=null)b.header("X-CSRF-TOKEN",csrf);var r=client.send(b.build(),HttpResponse.BodyHandlers.ofString());for(String c:r.headers().allValues("Set-Cookie"))if(c.startsWith("CINENEST_SESSION="))cookie=c.split(";",2)[0];return r;}
  void csrf(String path)throws Exception{var r=call("GET",path,null,false);assertThat(r.statusCode()).isEqualTo(200);csrf=JSONObjectUtils.parse(r.body()).get("token").toString();}
  UUID login()throws Exception{String email="p"+UUID.randomUUID().toString().replace("-","")+"@example.test";csrf("/api/auth/csrf");assertThat(call("POST","/api/auth/registrations",JSONObjectUtils.toJSONString(Map.of("email",email,"password",PASSWORD)),true).statusCode()).isEqualTo(202);String token=null;try(var files=Files.list(OUTBOX)){for(var f:files.toList()){var lines=Files.readAllLines(f);if(lines.get(1).equals(email))token=lines.get(2);}}assertThat(token).isNotNull();assertThat(call("POST","/api/auth/email-verifications",JSONObjectUtils.toJSONString(Map.of("token",token)),true).statusCode()).isEqualTo(204);String before=cookie;assertThat(call("POST","/api/auth/login",JSONObjectUtils.toJSONString(Map.of("email",email,"password",PASSWORD)),true).statusCode()).isEqualTo(204);assertThat(cookie).isNotEqualTo(before);csrf("/api/session/csrf");return jdbc.sql("SELECT account_id FROM cinenest_identity.manual_customer WHERE email=:email").param("email",email).query(UUID.class).single();}
  HttpResponse<String> update(long revision,String name)throws Exception{return call("PUT","/api/accounts/me/profile",JSONObjectUtils.toJSONString(new LinkedHashMap<>(Map.of("fullName",name,"phone","+94 77 123 4567","expectedRevision",revision))),true);}
 }
 long revision(UUID id){return jdbc.sql("SELECT revision FROM cinenest_identity.customer_profile WHERE account_id=:id").param("id",id).query(Long.class).single();}
 @Test void ownReadUpdatePersistenceAndLogout()throws Exception{var b=new Browser();UUID id=b.login();var initial=b.call("GET","/api/accounts/me/profile",null,false);assertThat(initial.statusCode()).isEqualTo(200);assertThat(initial.body()).contains("VERIFIED","MANUAL").doesNotContain("password_hash","verification_digest","subject");assertThat(JSONObjectUtils.parse(initial.body()).get("revision").toString()).isEqualTo("0");assertThat(b.update(0,"Local Profile Customer").statusCode()).isEqualTo(200);assertThat(revision(id)).isEqualTo(1);assertThat(b.call("GET","/api/accounts/me/profile",null,false).body()).contains("Local Profile Customer");assertThat(b.call("POST","/api/session/logout",null,true).statusCode()).isEqualTo(204);assertThat(b.call("GET","/api/accounts/me/profile",null,false).statusCode()).isEqualTo(401);}
 @Test void unauthenticatedCsrfMassAssignmentAndInvalidFieldsDenied()throws Exception{assertThat(new Browser().call("GET","/api/accounts/me/profile",null,false).statusCode()).isEqualTo(401);var b=new Browser();UUID id=b.login();assertThat(b.call("PUT","/api/accounts/me/profile","{}",false).statusCode()).isEqualTo(403);for(String json:List.of("{\"fullName\":\"Test\",\"phone\":null,\"expectedRevision\":0,\"accountStatus\":\"ELIGIBLE\"}","{\"fullName\":\"Test\",\"phone\":null,\"expectedRevision\":0,\"customerId\":\""+UUID.randomUUID()+"\"}","{\"fullName\":\"Test\",\"phone\":null,\"expectedRevision\":0,\"expectedRevision\":0}","{\"fullName\":\"\",\"phone\":null,\"expectedRevision\":0}","{\"fullName\":\"Test\",\"phone\":\"not a number\",\"expectedRevision\":0}","{\"fullName\":\"Test\",\"phone\":null,\"expectedRevision\":0.5}"))assertThat(b.call("PUT","/api/accounts/me/profile",json,true).statusCode()).isEqualTo(400);assertThat(jdbc.sql("SELECT count(*) FROM cinenest_identity.customer_profile WHERE account_id=:id").param("id",id).query(Integer.class).single()).isZero();assertThat(b.call("GET","/api/accounts/me/profile?customerId="+UUID.randomUUID(),null,false).statusCode()).isEqualTo(400);}
 @Test void noCrossCustomerOrStatusGrantMutations()throws Exception{var a=new Browser();UUID first=a.login();var b=new Browser();UUID second=b.login();long accountRevision=jdbc.sql("SELECT revision FROM cinenest_identity.account WHERE account_id=:id").param("id",first).query(Long.class).single();assertThat(a.update(0,"First Customer").statusCode()).isEqualTo(200);assertThat(b.update(0,"Second Customer").statusCode()).isEqualTo(200);assertThat(a.call("GET","/api/accounts/me/profile",null,false).body()).doesNotContain("Second Customer");assertThat(a.call("PUT","/api/accounts/"+second+"/profile","{}",true).statusCode()).isIn(403,404);assertThat(revision(second)).isEqualTo(1);assertThat(jdbc.sql("SELECT count(*) FROM cinenest_identity.access_grant WHERE account_id IN (:a,:b)").param("a",first).param("b",second).query(Integer.class).single()).isZero();assertThat(jdbc.sql("SELECT revision FROM cinenest_identity.account WHERE account_id=:id").param("id",first).query(Long.class).single()).isEqualTo(accountRevision);}
 @Test void concurrentSameRevisionHasOneWinner()throws Exception{var a=new Browser();UUID id=a.login();var b=new Browser();b.cookie=a.cookie;b.csrf=a.csrf;var executor=Executors.newFixedThreadPool(2);try{var one=executor.submit(()->a.update(0,"Concurrent One").statusCode());var two=executor.submit(()->b.update(0,"Concurrent Two").statusCode());assertThat(List.of(one.get(),two.get())).containsExactlyInAnyOrder(200,409);assertThat(revision(id)).isEqualTo(1);}finally{executor.shutdownNow();}}
 @Test void suspensionDeniesCurrentSessionAndNoProviderSecrets()throws Exception{var b=new Browser();UUID id=b.login();jdbc.sql("INSERT INTO cinenest_identity.external_identity VALUES('https://accounts.google.com','synthetic-google-sub',:id),('urn:cinenest:identity:facebook:app:synthetic','synthetic-facebook-sub',:id)").param("id",id).update();String body=b.call("GET","/api/accounts/me/profile",null,false).body();assertThat(body).contains("GOOGLE","FACEBOOK","MANUAL").doesNotContain("synthetic-google-sub","synthetic-facebook-sub","issuer");jdbc.sql("UPDATE cinenest_identity.account SET eligibility='SUSPENDED',revision=revision+1 WHERE account_id=:id").param("id",id).update();assertThat(b.call("GET","/api/accounts/me/profile",null,false).statusCode()).isEqualTo(403);assertThat(b.update(0,"Denied").statusCode()).isEqualTo(403);}
 @Test void mandatoryAuditRollbackAndImmutableDatabaseReceipts()throws Exception{var b=new Browser();UUID id=b.login();assertThat(b.update(0,"Original").statusCode()).isEqualTo(200);jdbc.sql("CREATE FUNCTION cinenest_identity.profile_test_fail() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'synthetic audit unavailable'; END $$").update();jdbc.sql("CREATE TRIGGER profile_test_fail BEFORE INSERT ON cinenest_identity.customer_profile_audit FOR EACH ROW EXECUTE FUNCTION cinenest_identity.profile_test_fail()").update();try{assertThat(b.update(1,"Must Roll Back").statusCode()).isEqualTo(503);assertThat(revision(id)).isEqualTo(1);assertThat(b.call("GET","/api/accounts/me/profile",null,false).statusCode()).isEqualTo(503);}finally{jdbc.sql("DROP TRIGGER profile_test_fail ON cinenest_identity.customer_profile_audit").update();jdbc.sql("DROP FUNCTION cinenest_identity.profile_test_fail()").update();}assertThatThrownBy(()->jdbc.sql("UPDATE cinenest_identity.customer_profile_audit SET outcome='DENY' WHERE account_id=:id").param("id",id).update()).isInstanceOf(Exception.class);assertThatThrownBy(()->jdbc.sql("UPDATE cinenest_identity.customer_profile SET revision=revision+2 WHERE account_id=:id").param("id",id).update()).isInstanceOf(Exception.class);assertThatThrownBy(()->jdbc.sql("UPDATE cinenest_identity.customer_profile SET revision=revision+1,full_name='No audit' WHERE account_id=:id").param("id",id).update()).isInstanceOf(Exception.class);assertThat(revision(id)).isEqualTo(1);}
 @Test void additiveUpgradePreservesV28Data()throws Exception{String database="profile_upgrade_"+UUID.randomUUID().toString().replace("-","");jdbc.sql("CREATE DATABASE "+database).update();String url=env.getRequiredProperty("spring.datasource.url");String target=url.substring(0,url.lastIndexOf('/')+1)+database;String user=env.getRequiredProperty("spring.datasource.username"),password=env.getRequiredProperty("spring.datasource.password");var old=org.flywaydb.core.Flyway.configure().dataSource(target,user,password).target("28").load();old.migrate();UUID id=UUID.randomUUID();try(var c=java.sql.DriverManager.getConnection(target,user,password);var s=c.createStatement()){s.execute("INSERT INTO cinenest_identity.account VALUES('"+id+"',true,'ELIGIBLE',7)");}var latest=org.flywaydb.core.Flyway.configure().dataSource(target,user,password).load();assertThat(latest.migrate().migrationsExecuted).isEqualTo(1);latest.validate();try(var c=java.sql.DriverManager.getConnection(target,user,password);var s=c.createStatement();var r=s.executeQuery("SELECT revision FROM cinenest_identity.account WHERE account_id='"+id+"'")){assertThat(r.next()).isTrue();assertThat(r.getLong(1)).isEqualTo(7);}assertThat(latest.info().current().getVersion().toString()).isEqualTo("29");}
 @Test @org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable(named="CINENEST_CUSTOMER_PROFILE_E2E",matches="true")
 void realBrowserProfileJourney()throws Exception {
  var run=Files.createTempDirectory("cinenest-profile-e2e-");Files.writeString(run.resolve("config.json"),JSONObjectUtils.toJSONString(Map.of("backend",base(),"outbox",OUTBOX.toString())));
  var process=new ProcessBuilder("node",Path.of("../frontend/tests/customer-profile-e2e.mjs").toAbsolutePath().toString(),run.toString()).redirectErrorStream(true).redirectOutput(run.resolve("browser.log").toFile()).start();
  try{assertThat(process.waitFor(3,TimeUnit.MINUTES)).isTrue();assertThat(process.exitValue()).as("Profile browser qualification;inspect private local harness log").isZero();
   var result=JSONObjectUtils.parse(Files.readString(run.resolve("results.json")));assertThat(result.get("status")).isEqualTo("PASS");assertThat(result.get("interception")).isEqualTo(false);
   UUID id=jdbc.sql("SELECT account_id FROM cinenest_identity.manual_customer WHERE email='profile-browser@example.test'").query(UUID.class).single();assertThat(revision(id)).isEqualTo(2);
   assertThat(jdbc.sql("SELECT count(*) FROM cinenest_identity.customer_profile_audit WHERE account_id=:id AND action='UPDATE' AND outcome='ALLOW'").param("id",id).query(Integer.class).single()).isEqualTo(2);
   assertThat(jdbc.sql("SELECT count(*) FROM cinenest_identity.customer_profile_audit WHERE account_id=:id AND outcome='CONFLICT'").param("id",id).query(Integer.class).single()).isEqualTo(1);
   assertThat(jdbc.sql("SELECT count(*) FROM cinenest_identity.http_session WHERE principal_name=:id").param("id",id.toString()).query(Integer.class).single()).isZero();
   assertThat(jdbc.sql("SELECT count(*) FROM cinenest_identity.access_grant WHERE account_id=:id").param("id",id).query(Integer.class).single()).isZero();
   for(String table:List.of("cinenest_payments.bank_payment_request","cinenest_payments.incoming_payment_credit","cinenest_payments.payment_allocation","cinenest_booking.booking","cinenest_access.access_credential","cinenest_iot.device"))assertThat(jdbc.sql("SELECT count(*) FROM "+table).query(Integer.class).single()).isZero();
  }finally{if(process.isAlive()){process.destroy();process.waitFor(10,TimeUnit.SECONDS);}}
 }

}
